const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const langano = ee.Geometry.Point([38.78, 7.64]).buffer(8000);  // Lake Langano approx
    const abijata = ee.Geometry.Point([38.58, 7.60]).buffer(7000);  // Lake Abijata approx
    const both = langano.union(abijata);
    const exactStart = '2022-03-29';
    const exactEnd = '2022-03-30';
    const wideStart = '2022-03-26';
    const wideEnd = '2022-04-01';

    // 2. Helper functions
    function maskS2(img) {
      const qa = img.select('QA60');
      const cloud = qa.bitwiseAnd(1 << 10).neq(0).or(qa.bitwiseAnd(1 << 11).neq(0));
      return img.updateMask(cloud.not());
    }
    function maskLandsat(img) {
      const qa = img.select('QA_PIXEL');
      const cloud = qa.bitwiseAnd(1 << 3).neq(0);
      const cloudShadow = qa.bitwiseAnd(1 << 4).neq(0);
      const dilated = qa.bitwiseAnd(1 << 1).neq(0);
      const mask = cloud.or(cloudShadow).or(dilated).not();
      // Scale reflectance (C2 L2)
      const scaled = img.select(['SR_B2','SR_B3','SR_B4','SR_B5']).multiply(0.0000275).add(-0.2)
                        .addBands(img.select(['QA_PIXEL']), null, true);
      return scaled.updateMask(mask);
    }
    function computeStats(img, bands, region) {
      const ndti = img.normalizedDifference([bands.red, bands.green]).rename('ndti');
      const ndwi = img.normalizedDifference([bands.green, bands.nir]);
      const waterMask = ndwi.gt(0.05);
      const ndtiWater = ndti.updateMask(waterMask);
      const stats = ndtiWater.reduceRegion({
        reducer: ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
        geometry: region,
        scale: 1000,
        maxPixels: 1e9,
        bestEffort: true
      });
      return {
        mean: ee.Number(stats.get('ndti_mean')),
        count: ee.Number(stats.get('ndti_count'))
      };
    }

    // 3. Data Acquisition & Check with fallback
    let source = null, start = exactStart, end = exactEnd, composite = null, nImages = 0, cloudMean = null;

    // Try S2 L2A exact day
    let col = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterDate(start, end)
      .filterBounds(both)
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 80));
    let size = await col.size().getInfo();
    if (size === 0) {
      // Widen S2 window
      start = wideStart; end = wideEnd;
      col = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
        .filterDate(start, end)
        .filterBounds(both)
        .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 80));
      size = await col.size().getInfo();
    }
    if (size > 0) {
      source = 'S2_SR';
      nImages = size;
      cloudMean = await col.aggregate_mean('CLOUDY_PIXEL_PERCENTAGE').getInfo();
      composite = col.map(maskS2).median();
      var bands = {red: 'B4', green: 'B3', nir: 'B8'};
    } else {
      // Fallback to Landsat 8/9 L2 (wider window)
      start = wideStart; end = wideEnd;
      let l8 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2').filterDate(start, end).filterBounds(both);
      let l9 = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2').filterDate(start, end).filterBounds(both);
      col = l8.merge(l9);
      size = await col.size().getInfo();
      if (size === 0) {
        console.log(`S2 Images: 0`);
        console.log(`Landsat Images: 0`);
        console.log('C1: Empty Collection (No images found in date/location for one or both comparison points).');
        console.log('C1');
        return;
      }
      source = 'LANDSAT_L2';
      nImages = size;
      // Mean cloud cover (if available)
      let cloudProp = 'CLOUD_COVER';
      try { cloudMean = await col.aggregate_mean(cloudProp).getInfo(); } catch (e) { cloudMean = null; }
      composite = col.map(maskLandsat).median();
      var bands = {red: 'SR_B4', green: 'SR_B3', nir: 'SR_B5'};
    }

    // 4. Processing and pixel counts
    const langStats = computeStats(composite, bands, langano);
    const abijStats = computeStats(composite, bands, abijata);

    const langCount = await langStats.count.getInfo();
    const abijCount = await abijStats.count.getInfo();

    const langMean = await langStats.mean.getInfo();
    const abijMean = await abijStats.mean.getInfo();

    console.log(`Dataset: ${source}, Window: ${start} to ${end}`);
    console.log(`Images: ${nImages}${cloudMean != null ? `, Cloud% mean: ${cloudMean.toFixed(1)}` : ''}`);
    console.log(`Langano Pixels: ${langCount}, NDTI mean: ${langMean !== null ? langMean.toFixed(4) : 'null'}`);
    console.log(`Abijata Pixels: ${abijCount}, NDTI mean: ${abijMean !== null ? abijMean.toFixed(4) : 'null'}`);

    // 5. Validation & Final Answer
    if ((langCount === 0) || (abijCount === 0)) {
      console.log('C2: No Valid Pixels (Images exist, but after cloud masking/processing, 0 pixels remain).');
      console.log('C2');
      return;
    }
    if (langMean === null || abijMean === null || isNaN(langMean) || isNaN(abijMean) ||
        Math.abs(langMean) > 1.0 || Math.abs(abijMean) > 1.0) {
      console.log('C3: Calculation Failure (Result is None/NaN or out of valid range).');
      console.log('C3');
      return;
    }

    if (langMean > abijMean) {
      console.log('A: Yes');
    } else {
      console.log('B: No');
    }

  } catch (err) {
    console.log(`Error: ${err.message}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
